import java.util.*;
import java.io.*;

public class Main {
    static final long MOD = 998244353L;

    static long add(long a, long b) {
        return ((a + b) % MOD + MOD) % MOD;
    }

    static long mul(long a, long b) {
        return ((a * b) % MOD + MOD) % MOD;
    }

    static long pow(long a, long e) {
        long r = 1;
        while (e > 0) {
            if ((e & 1) == 1) r = mul(r, a);
            a = mul(a, a);
            e >>= 1;
        }
        return r;
    }

    static long inv(long a) {
        return pow(a, MOD - 2);
    }

    static class FastScanner {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer("");

        String next() throws IOException {
            while (!st.hasMoreTokens()) {
                String line = br.readLine();
                if (line == null) throw new NoSuchElementException();
                st = new StringTokenizer(line);
            }
            return st.nextToken();
        }

        long nextLong() throws IOException {
            return Long.parseLong(next());
        }

        int nextInt() throws IOException {
            return Integer.parseInt(next());
        }
    }

    public static void main(String[] args) throws IOException {
        FastScanner sc = new FastScanner();
        long n = sc.nextLong();
        long m = sc.nextLong();
        int k = sc.nextInt();

        long[][] dp = new long[k + 1][k + 1];
        dp[0][0] = 1;

        for (int i = 0; i < k; i++) {
            for (int j = 0; j < k; j++) {
                dp[i + 1][j] = add(dp[i + 1][j], mul(dp[i][j], j));
                dp[i + 1][j + 1] = add(dp[i + 1][j + 1], mul(dp[i][j], n - j));
            }
        }

        long x = inv(m);
        long[] p = new long[k + 1];
        p[0] = 1;
        for (int i = 1; i <= k; i++) p[i] = mul(p[i - 1], x);

        long ans = 0;
        for (int i = 1; i <= k; i++) ans = add(ans, mul(dp[k][i], p[i]));
        System.out.println(ans);
    }
}
